"""Session 2482: Statistics Canada's table 25-10-0084-01, electricity generated by fuel at thermal power plants.

Energy Research Warehouse (ERW). Tests warehouse/connectors/statcan_thermal_fuel.py on a zip built here in the download's
form (made up for the test, not StatCan's): each "<fuel>, electricity generated" line a row in MWh on the year's 1 January,
the fuel as a slug, a revision marked; the "fuel consumed" and "cost of fuel" lines not taken and counted; a figure marked
".." not written and counted; a generation line not in megawatt hours, an area, class or status not in the map and a key
given twice stopping the run; the sector rule and the holds. No network.

    python -m unittest tests.test_session2482 -v
"""

import csv
import io
import os
import sys
import unittest
import zipfile

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, os.path.join(ROOT, "warehouse", "connectors"))
sys.path.insert(0, os.path.join(ROOT, "warehouse", "metadata"))
sys.path.insert(0, os.path.join(ROOT, "warehouse", "redivis"))
import statcan_thermal_fuel as S  # noqa: E402
import build_coverage as B  # noqa: E402
import release_v1 as R  # noqa: E402

BASE = {"source": "s", "source_url": "u", "retrieved_at": "r", "vintage": "v"}
COLS = ["REF_DATE", "GEO", "DGUID", "North American Industry Classification System (NAICS)", "Fuel type", "UOM", "UOM_ID", "SCALAR_FACTOR",
        "SCALAR_ID", "VECTOR", "COORDINATE", "VALUE", "STATUS", "SYMBOL", "TERMINATED", "DECIMALS"]


def row(year="2025", geo="Alberta", klass="Electricity producers, electricity utilities [2211]", fuel="Natural gas, electricity generated",
        uom="Megawatt hours", scalar="units", value="60000000", status="", symbol=""):
    return [year, geo, "", klass, fuel, uom, "", scalar, "0", "v7", "1.1.1", value, status, symbol, "", "0"]


def build(rows):
    b = io.StringIO()
    w = csv.writer(b)
    w.writerow(COLS)
    w.writerows(rows)
    z = io.BytesIO()
    with zipfile.ZipFile(z, "w") as f:
        f.writestr("25100084.csv", b.getvalue())
        f.writestr("25100084_MetaData.csv", "x")
    return z.getvalue()


class Parse(unittest.TestCase):
    def test_rows(self):
        counts = {}
        out = S.parse(build([row(), row(geo="Canada", klass="Total all classes of electricity", fuel="Uranium, electricity generated", value="81500000.5", symbol="r"),
                             row(fuel="Natural gas, fuel consumed", uom="Cubic metres", scalar="thousands", value="9"),
                             row(fuel="Natural gas, cost of fuel", uom="Dollars", scalar="thousands", value="9"),
                             row(fuel="Lignite, electricity generated", value="", status="..")]), BASE, counts)
        self.assertEqual(len(out), 2)
        a = out[0]
        self.assertEqual((a["entity"], a["variable"], a["ts_utc"], a["value"], a["unit"], a["geo"], a["x_fuel"]),
                         ("statcan_tf:ab:utilities", "generation_natural_gas", "2025-01-01T00:00:00Z", 60000000.0, "MWh", "CA-AB", "Natural gas"))
        self.assertEqual((out[1]["entity"], out[1]["variable"], out[1]["x_revised"]), ("statcan_tf:ca:all", "generation_uranium", "r"))
        self.assertEqual(counts, {"fuel consumed rows not taken": 1, "cost of fuel rows not taken": 1, "..": 1})

    def test_stops(self):
        for rows in ([row(uom="Gigawatt hours")], [row(geo="Atlantis")], [row(klass="Households")], [row(status="F", value="")], [row(), row()]):
            with self.assertRaises(RuntimeError):
                S.parse(build(rows), BASE, {})


class Registered(unittest.TestCase):
    def test_sector_and_holds(self):
        self.assertEqual(B.sector_of(S.TABLE), "power")
        self.assertIn(S.TABLE, R.STORAGE_HELD)
        with open(os.path.join(ROOT, "warehouse", "supabase", "live_set.yaml"), encoding="utf-8") as f:
            self.assertIn(f"  - {S.TABLE}\n", f.read().replace("\r\n", "\n"))


if __name__ == "__main__":
    unittest.main()
